public static void fmAddMaintenanceRecord(FMVehicle vehicle, FMRental rental)
{

    FMVehicleMaintenance lastMaintenance, newRec;

    UnitofWork uoW;
    uoW = new UnitofWork();

    select firstonly maxof(DateCompleted) from lastMaintenance;

    newRec.fmVehicle(vehicle);
    newRec.Mileage = rental.EndMileage - lastMaintenance.Mileage;
    newRec.Status = FMStatus::New;
    newRec.DateStarted = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());

    uoW.insertonSaveChanges(newRec);
    uoW.saveChanges();

    // Activate a workflow for managing the vehicle maintenance process
    Workflow::activateFromWorkflowType('FMVehicleMaintenanceWorkflowType',
            newRec.RecId,
            'Automatically started workflow',
            NoYes::No,
            curUserId());

}
